MultiLanguageItemData['tw'][229201] = {name = "空氣之四", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一位呈禱告姿勢的騎士雕像，佇立於推測是他的墳墓。\""}
MultiLanguageItemData['tw'][229202] = {name = "空氣之五", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一個輕蔑的男人對兩個沮喪且退縮的人怒目而視，他們將風之袋留在了地上。他的左肩上扛著另外兩個袋子，第三個則在他的右手上。\""}
MultiLanguageItemData['tw'][229203] = {name = "空氣之六", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一位船主用他的船載著乘客到遙遠的海岸。航程很順利，且貨物輕盈，可以看出這份工作對他們來說綽綽有餘。\""}
MultiLanguageItemData['tw'][229204] = {name = "空氣之七", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一個正迅速將五股風帶離的人。另外兩股風在地上，附近有一個營地。\""}
MultiLanguageItemData['tw'][229205] = {name = "空氣之八", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一名被綁住、眼睛被蒙上的俘虜，周圍環繞著八股洶湧的狂風。不過，這只是短暫的束縛，而非無法掙脫的枷鎖。\""}
MultiLanguageItemData['tw'][229206] = {name = "火焰之一", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一隻從燃燒的火球裡伸出來的手，握著一把被煙霧環繞的魔杖。\""}
MultiLanguageItemData['tw'][229207] = {name = "火焰之二", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一個高大的人物從城垛屋頂眺望大海和海岸。他的右手握著一個球體，左手拿著一把燃燒的法杖，並將其靠在城垛上。另一把燃燒法杖被固定在人物右邊的圓環上。\""}
MultiLanguageItemData['tw'][229208] = {name = "火焰之三", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一個冷靜、有威嚴的人物，他正轉過身從懸崖的邊緣看著海上來往的船隻。三把護杖被安置在地上，每一把都掛著一個燈籠，人物稍微靠向其中一把。\""}
MultiLanguageItemData['tw'][229209] = {name = "火焰之四", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著四根大型柱子，柱子之間懸掛著一個由最純淨的火焰形成的宏偉花環。兩個人物拿著芬芳的花朵，他們的身邊有一座護城河橋，通往一座古老的莊園。\""}
MultiLanguageItemData['tw'][229210] = {name = "火焰之五", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著五個正在揮舞護杖的青年，就像在運動一樣。這是在模擬戰場，他們的眼中燃燒著火光。\""}
MultiLanguageItemData['tw'][229211] = {name = "火焰之六", additional_info = "暗月命運套卡\n[q]\"這張牌描繪著一個騎在馬上的人物，他戴著桂冠並持有火焰之劍。人物的身邊有五位持有相似火焰之劍的步兵。\""}
